                float distance = m_params.GetDistance();
                player->SetDistance(distance);
            }
        }
    }
    if (m_dirty & 6) {
        CheckState(-1);
        if (HasPositiveGain(manager)) {
            if (IsPlayingVirtual()) {
                ReturnToIdle(manager);
                Play(manager);
            }
        } else if (IsWaitingOrPlayingPhysical()) {
            ReturnToIdle(manager);
            PlayVirtual(manager);
        }
    }
    m_dirty = 0;
}

